import { sql } from 'drizzle-orm';
import { index, integer, jsonb, pgTable, text, timestamp, uuid } from 'drizzle-orm/pg-core';

// Conventions (as in identity): UUIDv7 ids generated by the application, timestamptz, statuses as
// text + CHECK. Every tenant-owned table has organization_id and a unique (organization_id, id)
// key so other tables can reference it with a composite foreign key: a reference into another
// tenant is then not just filtered out, it cannot be written at all.

const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

/**
 * Events recorded in the same transaction as the change they describe. The relay that publishes
 * them to RabbitMQ is built with message ingestion.
 */
export const outboxEvents = pgTable(
  'outbox_events',
  {
    id: uuid('id').primaryKey(),
    type: text('type').notNull(),
    version: integer('version').notNull(),
    occurredAt: timestamptz('occurred_at').notNull(),
    organizationId: uuid('organization_id'),
    actorId: uuid('actor_id'),
    correlationId: text('correlation_id').notNull(),
    causationId: uuid('causation_id'),
    payload: jsonb('payload').notNull(),
    publishedAt: timestamptz('published_at'),
  },
  (table) => [
    index('outbox_events_unpublished_idx')
      .on(table.occurredAt)
      .where(sql`${table.publishedAt} is null`),
  ],
);

export const schema = { outboxEvents };
export type OperationsSchema = typeof schema;
